/* Podcast Monitor dashboard.
 * Reads static JSON (config/podcasts.json, config/taxonomy.json,
 * data/episodes.json, data/state.json) generated by pipeline/run.py.
 * No network calls beyond those local files -- zero ongoing token cost.
 */

const state = {
  podcasts: [],
  categories: [],
  categoriesById: {},
  taxonomy: null,
  labels: { sectors: {}, themes: {}, stocks: {} },
  episodes: [],
  runState: null,
  hiddenPodcasts: new Set(JSON.parse(localStorage.getItem("pm_hidden_podcasts") || "[]")),
  filters: {
    entity: null, // { kind: 'sectors'|'themes'|'stocks', id }
    days: 90,
    search: "",
    podcastQuery: "",
  },
};

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

function cacheBust(url) {
  return url + (url.includes("?") ? "&" : "?") + "t=" + Date.now();
}

async function loadJSON(path, bust = false) {
  const res = await fetch(bust ? cacheBust(path) : path);
  if (!res.ok) throw new Error(`Failed to load ${path}: ${res.status}`);
  return res.json();
}

function isDarkMode() {
  return document.documentElement.getAttribute("data-theme") === "dark" ||
    (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches &&
     document.documentElement.getAttribute("data-theme") !== "light");
}

function categoryColor(categoryId) {
  const cat = state.categoriesById[categoryId];
  if (!cat) return "#898781";
  return (isDarkMode() && cat.color_dark) ? cat.color_dark : cat.color;
}

function podcastColor(podcast) {
  return categoryColor(podcast.category);
}

function isPodcastActive(podcast) {
  return podcast.active !== false && !state.hiddenPodcasts.has(podcast.id);
}

function buildLabelMaps() {
  for (const kind of ["sectors", "themes", "stocks"]) {
    state.labels[kind] = {};
    for (const entry of state.taxonomy[kind]) state.labels[kind][entry.id] = entry.label;
  }
}

function sentimentClass(score) {
  if (score > 0.15) return "bullish";
  if (score < -0.15) return "bearish";
  return "neutral";
}
function sentimentWord(score) {
  if (score > 0.15) return "Bullish";
  if (score < -0.15) return "Bearish";
  return "Mixed / neutral";
}

/* ---------------- Filtering ---------------- */

function cutoffDate() {
  if (state.filters.days === "all") return null;
  const d = new Date();
  d.setDate(d.getDate() - state.filters.days);
  return d;
}

function episodeMatchesEntity(ep) {
  const f = state.filters.entity;
  if (!f) return true;
  return (ep.tags[f.kind] || []).includes(f.id);
}

function episodeMatchesSearch(ep) {
  const q = state.filters.search.trim().toLowerCase();
  if (!q) return true;
  return ep.title.toLowerCase().includes(q) || (ep.summary || "").toLowerCase().includes(q);
}

function getFilteredEpisodes() {
  const cutoff = cutoffDate();
  const activeIds = new Set(state.podcasts.filter(isPodcastActive).map((p) => p.id));
  return state.episodes.filter((ep) => {
    if (!activeIds.has(ep.podcast_id)) return false;
    if (cutoff && ep.published_at && new Date(ep.published_at) < cutoff) return false;
    if (!episodeMatchesEntity(ep)) return false;
    if (!episodeMatchesSearch(ep)) return false;
    return true;
  });
}

/* ---------------- Aggregation (client-side, over the current filter slice) ---------------- */

function aggregateBy(kind, episodes) {
  const totals = new Map();
  for (const ep of episodes) {
    for (const id of ep.tags[kind] || []) {
      if (!totals.has(id)) totals.set(id, { id, mentions: 0, sentimentSum: 0 });
      const t = totals.get(id);
      t.mentions += 1;
      t.sentimentSum += ep.tags.sentiment || 0;
    }
  }
  return Array.from(totals.values())
    .map((t) => ({ ...t, label: state.labels[kind][t.id] || t.id, avgSentiment: t.sentimentSum / t.mentions }))
    .sort((a, b) => b.mentions - a.mentions);
}

function monthKey(iso) {
  return iso ? iso.slice(0, 7) : null;
}

function lastNMonths(n) {
  const out = [];
  const d = new Date();
  d.setDate(1);
  for (let i = 0; i < n; i++) {
    out.unshift(d.toISOString().slice(0, 7));
    d.setMonth(d.getMonth() - 1);
  }
  return out;
}

function monthLabel(key) {
  const [y, m] = key.split("-").map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString(undefined, { month: "short" });
}

/* ---------------- Rendering ---------------- */

function renderStatTiles(episodes) {
  const tagged = episodes.filter((e) => (e.tags.sectors.length || e.tags.themes.length || e.tags.stocks.length));
  const totalMentions = tagged.reduce((acc, e) => acc + e.tags.sectors.length + e.tags.themes.length + e.tags.stocks.length, 0);
  const avgSentiment = tagged.length ? tagged.reduce((a, e) => a + (e.tags.sentiment || 0), 0) / tagged.length : 0;

  // rising theme: compare mentions in most recent 30d vs prior 30d, across whatever entity kind is broadest (themes)
  const now = new Date();
  const d30 = new Date(now); d30.setDate(d30.getDate() - 30);
  const d60 = new Date(now); d60.setDate(d60.getDate() - 60);
  const recent = episodes.filter((e) => e.published_at && new Date(e.published_at) >= d30);
  const prior = episodes.filter((e) => e.published_at && new Date(e.published_at) >= d60 && new Date(e.published_at) < d30);
  const recentAgg = aggregateBy("themes", recent);
  const priorMap = new Map(aggregateBy("themes", prior).map((t) => [t.id, t.mentions]));
  let riser = null;
  for (const t of recentAgg) {
    const before = priorMap.get(t.id) || 0;
    const delta = t.mentions - before;
    if (!riser || delta > riser.delta) riser = { label: t.label, delta, mentions: t.mentions };
  }

  const grid = $("#stat-grid");
  grid.innerHTML = "";
  const tiles = [
    { label: "Episodes in view", value: episodes.length.toLocaleString() },
    { label: "Tagged mentions", value: totalMentions.toLocaleString(), hint: `${tagged.length} episodes with a signal` },
    {
      label: "Net sentiment", value: sentimentWord(avgSentiment),
      hint: `score ${avgSentiment >= 0 ? "+" : ""}${avgSentiment.toFixed(2)}`, sentiment: avgSentiment,
    },
    {
      label: "Fastest-rising theme (30d)",
      value: riser && riser.delta > 0 ? riser.label : "—",
      hint: riser && riser.delta > 0 ? `+${riser.delta} mentions vs prior 30d` : "No clear riser yet",
    },
  ];
  for (const t of tiles) {
    const el = document.createElement("div");
    el.className = "stat-tile";
    const deltaClass = t.sentiment > 0.15 ? "up" : t.sentiment < -0.15 ? "down" : "flat";
    el.innerHTML = `
      <div class="stat-label"></div>
      <div class="stat-value"></div>
      <div class="stat-delta ${t.sentiment !== undefined ? deltaClass : "flat"}"></div>
    `;
    el.querySelector(".stat-label").textContent = t.label;
    el.querySelector(".stat-value").textContent = t.value;
    el.querySelector(".stat-delta").textContent = t.hint || "";
    grid.appendChild(el);
  }
}

function renderBarList(containerId, kind, episodes, limit = 8) {
  const container = $(containerId);
  const agg = aggregateBy(kind, episodes).slice(0, limit);
  container.innerHTML = "";
  if (!agg.length) {
    container.innerHTML = `<div class="empty-state">No mentions in this window.</div>`;
    return;
  }
  const max = Math.max(...agg.map((a) => a.mentions));
  for (const item of agg) {
    const row = document.createElement("div");
    row.className = "bar-row";
    const pct = Math.max(4, Math.round((item.mentions / max) * 100));
    const color = item.avgSentiment > 0.15 ? "var(--good)" : item.avgSentiment < -0.15 ? "var(--critical)" : "var(--ink-muted)";
    row.innerHTML = `
      <div class="label" tabindex="0" role="button"></div>
      <div class="bar-track"><div class="bar-fill" style="width:${pct}%; background:${color}"></div></div>
      <div class="value"></div>
    `;
    row.querySelector(".label").textContent = item.label;
    row.querySelector(".value").textContent = item.mentions;
    row.querySelector(".label").addEventListener("click", () => {
      setEntityFilter(kind, item.id, item.label);
    });
    container.appendChild(row);
  }
}

const TREND_BAR_AREA_PX = 160;

function renderTrendChart(episodes) {
  // Grouped by category, not individual podcast: with 100+ shows tracked,
  // per-podcast segments stop being readable. Category (5-6 groups) keeps
  // this chart legible; use the "Podcasts" filter to narrow to specific shows.
  const months = lastNMonths(6);
  const container = $("#trend-chart");
  container.innerHTML = "";
  const podcastsById = Object.fromEntries(state.podcasts.map((p) => [p.id, p]));
  const activeCategories = state.categories.filter((c) =>
    state.podcasts.some((p) => p.category === c.id && isPodcastActive(p))
  );

  const data = months.map((m) => {
    const row = { month: m, byCategory: {}, total: 0 };
    for (const c of activeCategories) row.byCategory[c.id] = 0;
    return row;
  });
  const idxByMonth = new Map(data.map((d, i) => [d.month, i]));

  for (const ep of episodes) {
    const mk = monthKey(ep.published_at);
    if (!idxByMonth.has(mk)) continue;
    const podcast = podcastsById[ep.podcast_id];
    if (!podcast || !isPodcastActive(podcast)) continue;
    const row = data[idxByMonth.get(mk)];
    if (!(podcast.category in row.byCategory)) continue;
    row.byCategory[podcast.category] += 1;
    row.total += 1;
  }

  const max = Math.max(1, ...data.map((d) => d.total));

  for (const row of data) {
    const wrap = document.createElement("div");
    wrap.style.flex = "1";
    wrap.style.display = "flex";
    wrap.style.flexDirection = "column";
    wrap.style.alignItems = "stretch";
    wrap.style.minWidth = "0";

    const barArea = document.createElement("div");
    barArea.style.height = TREND_BAR_AREA_PX + "px";
    barArea.style.display = "flex";
    barArea.style.flexDirection = "column-reverse";

    activeCategories.forEach((c, i) => {
      const count = row.byCategory[c.id];
      if (count === 0) return;
      const heightPx = Math.max(3, Math.round((count / max) * TREND_BAR_AREA_PX));
      const seg = document.createElement("div");
      seg.className = "trend-seg";
      seg.dataset.category = c.id;
      seg.dataset.count = String(count);
      seg.dataset.month = row.month;
      seg.style.height = heightPx + "px";
      seg.style.background = categoryColor(c.id);
      seg.style.marginBottom = i < activeCategories.length - 1 ? "2px" : "0";
      barArea.appendChild(seg);
    });

    const monthLabelEl = document.createElement("div");
    monthLabelEl.className = "trend-col-label";
    monthLabelEl.textContent = monthLabel(row.month);

    wrap.appendChild(barArea);
    wrap.appendChild(monthLabelEl);
    container.appendChild(wrap);
  }

  attachTrendTooltips(container);
  renderTrendLegend(activeCategories);
}

function renderTrendLegend(categories) {
  const legend = $("#trend-legend");
  legend.innerHTML = "";
  for (const c of categories) {
    const item = document.createElement("span");
    item.className = "legend-item";
    item.innerHTML = `<span class="swatch" style="background:${categoryColor(c.id)}"></span>`;
    item.append(document.createTextNode(c.label));
    legend.appendChild(item);
  }
}

const tooltipEl = document.createElement("div");
tooltipEl.className = "tooltip";
document.body.appendChild(tooltipEl);

function showTooltip(x, y, title, rows) {
  tooltipEl.innerHTML = `<div class="t-title"></div>`;
  tooltipEl.querySelector(".t-title").textContent = title;
  for (const r of rows) {
    const rowEl = document.createElement("div");
    rowEl.className = "t-row";
    rowEl.innerHTML = `<span class="t-label"></span><span class="t-val"></span>`;
    rowEl.querySelector(".t-label").textContent = r.label;
    rowEl.querySelector(".t-val").textContent = r.value;
    tooltipEl.appendChild(rowEl);
  }
  tooltipEl.style.left = Math.min(x + 12, window.innerWidth - 260) + "px";
  tooltipEl.style.top = Math.max(y - 10, 8) + "px";
  tooltipEl.classList.add("visible");
}
function hideTooltip() { tooltipEl.classList.remove("visible"); }

function attachTrendTooltips(container) {
  $$(".trend-seg", container).forEach((seg) => {
    seg.addEventListener("pointermove", (e) => {
      const categoryId = seg.dataset.category;
      const c = state.categoriesById[categoryId];
      const month = seg.dataset.month;
      showTooltip(e.clientX, e.clientY, `${c ? c.label : categoryId} — ${monthLabel(month)}`, [
        { label: "Episodes", value: seg.dataset.count },
      ]);
    });
    seg.addEventListener("pointerleave", hideTooltip);
  });
}

function renderEpisodeTable(episodes) {
  const tbody = $("#episode-table-body");
  tbody.innerHTML = "";
  const sorted = [...episodes].sort((a, b) => (b.published_at || "").localeCompare(a.published_at || ""));
  if (!sorted.length) {
    tbody.innerHTML = `<tr><td colspan="5" class="empty-state">No episodes match the current filters.</td></tr>`;
    return;
  }
  for (const ep of sorted.slice(0, 200)) {
    const podcast = state.podcasts.find((p) => p.id === ep.podcast_id);
    const tr = document.createElement("tr");
    const dateStr = ep.published_at ? new Date(ep.published_at).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" }) : "—";

    const tagIds = [
      ...(ep.tags.themes || []).map((id) => ({ kind: "themes", id })),
      ...(ep.tags.sectors || []).map((id) => ({ kind: "sectors", id })),
      ...(ep.tags.stocks || []).map((id) => ({ kind: "stocks", id })),
    ].slice(0, 6);

    tr.innerHTML = `
      <td class="ep-date"></td>
      <td></td>
      <td class="ep-title"></td>
      <td class="ep-tags"></td>
      <td></td>
    `;
    tr.children[0].textContent = dateStr;

    const podcastCell = tr.children[1];
    const badge = document.createElement("span");
    badge.className = "ep-podcast";
    badge.innerHTML = `<span class="dot" style="background:${podcast ? podcastColor(podcast) : "#999"}"></span>`;
    badge.append(document.createTextNode(podcast ? podcast.name : ep.podcast_id));
    podcastCell.appendChild(badge);

    const titleCell = tr.children[2];
    if (ep.link) {
      const a = document.createElement("a");
      a.href = ep.link; a.target = "_blank"; a.rel = "noopener";
      a.textContent = ep.title;
      titleCell.appendChild(a);
    } else {
      titleCell.textContent = ep.title;
    }

    const tagsCell = tr.children[3];
    for (const t of tagIds) {
      const pill = document.createElement("span");
      pill.className = "tag-pill";
      pill.textContent = state.labels[t.kind][t.id] || t.id;
      pill.style.cursor = "pointer";
      pill.addEventListener("click", () => setEntityFilter(t.kind, t.id, state.labels[t.kind][t.id] || t.id));
      tagsCell.appendChild(pill);
    }

    const sentCell = tr.children[4];
    const sc = sentimentClass(ep.tags.sentiment || 0);
    const sentSpan = document.createElement("span");
    sentSpan.className = `sent-tag ${sc}`;
    sentSpan.textContent = sc === "bullish" ? "Bullish" : sc === "bearish" ? "Bearish" : "Neutral";
    sentCell.appendChild(sentSpan);

    tbody.appendChild(tr);
  }
}

function renderEntitySelect() {
  const select = $("#entity-select");
  const current = select.value;
  select.innerHTML = `<option value="">All themes / sectors / stocks</option>`;
  const groups = [
    ["themes", "Themes"],
    ["sectors", "Sectors"],
    ["stocks", "Stocks"],
  ];
  for (const [kind, label] of groups) {
    const optgroup = document.createElement("optgroup");
    optgroup.label = label;
    const entries = state.taxonomy[kind].slice().sort((a, b) => a.label.localeCompare(b.label));
    for (const entry of entries) {
      const opt = document.createElement("option");
      opt.value = `${kind}:${entry.id}`;
      opt.textContent = entry.label;
      optgroup.appendChild(opt);
    }
    select.appendChild(optgroup);
  }
  if (current) select.value = current;
}

function setEntityFilter(kind, id, label) {
  state.filters.entity = { kind, id, label };
  $("#entity-select").value = `${kind}:${id}`;
  renderAll();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function renderPodcastChips() {
  const row = $("#podcast-chips");
  row.innerHTML = "";
  for (const p of state.podcasts) {
    const active = isPodcastActive(p);
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = `chip ${active ? "active" : "inactive"}`;
    chip.style.color = active ? podcastColor(p) : "";
    chip.innerHTML = `<span class="dot" style="background:${podcastColor(p)}"></span>`;
    chip.append(document.createTextNode(p.name));
    chip.addEventListener("click", () => {
      if (state.hiddenPodcasts.has(p.id)) state.hiddenPodcasts.delete(p.id);
      else state.hiddenPodcasts.add(p.id);
      persistHidden();
      renderAll();
    });
    row.appendChild(chip);
  }
}

function persistHidden() {
  localStorage.setItem("pm_hidden_podcasts", JSON.stringify(Array.from(state.hiddenPodcasts)));
}

function renderActiveFilterSummary() {
  const el = $("#active-entity-label");
  if (state.filters.entity) {
    el.textContent = `Filtered to: ${state.filters.entity.label}`;
    el.style.display = "inline";
  } else {
    el.style.display = "none";
  }
}

function renderLastUpdated() {
  const el = $("#status-line");
  if (!state.runState || !state.runState.last_run_at) {
    el.innerHTML = `Data not yet generated — run <strong>pipeline/run.py</strong>`;
    return;
  }
  const d = new Date(state.runState.last_run_at);
  el.innerHTML = `Last updated <strong>${d.toLocaleString()}</strong> · ${state.runState.episode_count} episodes tracked`;
}

function renderAll() {
  const episodes = getFilteredEpisodes();
  renderPodcastChips();
  renderActiveFilterSummary();
  renderStatTiles(episodes);
  renderBarList("#top-themes", "themes", episodes);
  renderBarList("#top-sectors", "sectors", episodes);
  renderBarList("#top-stocks", "stocks", episodes);
  renderTrendChart(episodes);
  renderEpisodeTable(episodes);
}

/* ---------------- Settings / manage podcasts ---------------- */

function renderSettings() {
  const list = $("#podcast-manage-list");
  list.innerHTML = "";
  for (const p of state.podcasts) {
    const row = document.createElement("div");
    row.className = "podcast-manage-row";
    row.innerHTML = `
      <div class="meta">
        <span class="dot" style="background:${podcastColor(p)}"></span>
        <div>
          <div class="name"></div>
          <div class="publisher"></div>
        </div>
      </div>
    `;
    row.querySelector(".name").textContent = p.name;
    row.querySelector(".publisher").textContent = `${p.publisher} · shown on dashboard: ${isPodcastActive(p) ? "yes" : "no"}`;
    const toggle = document.createElement("button");
    toggle.className = `switch ${isPodcastActive(p) ? "on" : ""}`;
    toggle.title = "Show/hide on this device (does not edit the repo)";
    toggle.addEventListener("click", () => {
      if (state.hiddenPodcasts.has(p.id)) state.hiddenPodcasts.delete(p.id);
      else state.hiddenPodcasts.add(p.id);
      persistHidden();
      renderSettings();
      renderAll();
    });
    row.appendChild(toggle);
    list.appendChild(row);
  }
}

function setupAddPodcastForm() {
  const btn = $("#generate-config-btn");
  btn.addEventListener("click", () => {
    const name = $("#new-podcast-name").value.trim();
    const feed = $("#new-podcast-feed").value.trim();
    const publisher = $("#new-podcast-publisher").value.trim() || "Independent";
    if (!name || !feed) {
      $("#new-podcast-output").textContent = "Enter at least a name and an RSS feed URL.";
      return;
    }
    const id = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
    const categoryIds = state.categories.map((c) => c.id).join(" | ");
    const snippet = {
      id, name, publisher, feed_url: feed,
      category: `<one of: ${categoryIds}>`, active: true,
    };
    $("#new-podcast-output").textContent =
      "Add this entry to config/podcasts.json (set category to one of the ids shown), " +
      "then commit + push (or wait for the next scheduled run):\n\n" + JSON.stringify(snippet, null, 2);
  });
}

/* ---------------- Wiring ---------------- */

function setupTabs() {
  $$(".tab").forEach((tab) => {
    tab.addEventListener("click", () => {
      $$(".tab").forEach((t) => t.classList.remove("active"));
      $$(".view").forEach((v) => v.classList.remove("active"));
      tab.classList.add("active");
      $(`#view-${tab.dataset.view}`).classList.add("active");
    });
  });
}

function setupFilters() {
  $("#date-range").addEventListener("change", (e) => {
    const v = e.target.value;
    state.filters.days = v === "all" ? "all" : Number(v);
    renderAll();
  });
  $("#entity-select").addEventListener("change", (e) => {
    if (!e.target.value) { state.filters.entity = null; renderAll(); return; }
    const [kind, id] = e.target.value.split(":");
    state.filters.entity = { kind, id, label: state.labels[kind][id] || id };
    renderAll();
  });
  $("#search-input").addEventListener("input", (e) => {
    state.filters.search = e.target.value;
    renderAll();
  });
  $("#clear-filters").addEventListener("click", () => {
    state.filters.entity = null;
    state.filters.search = "";
    state.filters.days = 90;
    $("#entity-select").value = "";
    $("#search-input").value = "";
    $("#date-range").value = "90";
    renderAll();
  });
}

async function loadAllData(bust = false) {
  const [podcastsCfg, categoriesCfg, taxonomy, episodes, runState] = await Promise.all([
    loadJSON("config/podcasts.json", bust),
    loadJSON("config/categories.json", bust),
    loadJSON("config/taxonomy.json", bust),
    loadJSON("data/episodes.json", bust),
    loadJSON("data/state.json", bust).catch(() => null),
  ]);
  state.podcasts = podcastsCfg.podcasts;
  state.categories = categoriesCfg.categories;
  state.categoriesById = Object.fromEntries(state.categories.map((c) => [c.id, c]));
  state.taxonomy = taxonomy;
  state.episodes = episodes;
  state.runState = runState;
  buildLabelMaps();
  renderEntitySelect();
}

async function refresh(showSpinner = true) {
  const btn = $("#refresh-btn");
  if (showSpinner) {
    btn.disabled = true;
    btn.querySelector(".icon").classList.add("icon-spin");
  }
  try {
    await loadAllData(true);
    renderLastUpdated();
    renderAll();
    renderSettings();
  } catch (err) {
    console.error(err);
    $("#status-line").textContent = "Refresh failed — check console.";
  } finally {
    if (showSpinner) {
      btn.disabled = false;
      btn.querySelector(".icon").classList.remove("icon-spin");
    }
  }
}

async function init() {
  setupTabs();
  setupFilters();
  setupAddPodcastForm();
  $("#refresh-btn").addEventListener("click", () => refresh(true));

  try {
    await loadAllData(false);
    renderLastUpdated();
    renderAll();
    renderSettings();
  } catch (err) {
    console.error(err);
    $("#status-line").textContent = "Could not load data/episodes.json yet — run the pipeline first.";
  }
}

document.addEventListener("DOMContentLoaded", init);
